mapper.select:
SELECT CAST(COUNT(*) AS INTEGER)
FROM information_schema.columns
WHERE LOWER(table_schema) = 'public'
  AND table_name = #{tableName}
  AND column_name = #{columnName}

mapper.update:
UPDATE chat_room_member
SET last_read_at = now()
WHERE room_idx = #{roomIdx}
  AND user_id = #{userId}

choose.when:
UPDATE chat_room_member
SET hidden_at = now()
WHERE room_idx = #{roomIdx}
  AND user_id = #{userId}

choose.otherwise:
DELETE FROM chat_room_member
WHERE room_idx = #{roomIdx}
  AND user_id = #{userId}

mapper.update:
UPDATE chat_room_member
SET hidden_at = NULL
WHERE room_idx = #{roomIdx}
  AND user_id = #{userId}
  AND hidden_at IS NOT NULL

UPDATE chat_message
SET deleted_at = now()
WHERE message_idx = #{messageIdx}
  AND sender_id = #{senderId}
  AND deleted_at IS NULL

mapper.select:
SELECT COUNT(*)
FROM chat_room_member
WHERE room_idx = #{roomIdx}
  AND user_id = #{userId}
